<?php
namespace App\Models;use App\Enums\TechnicianWorkingStatus;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\SoftDeletes;
class Technician extends Model{use HasFactory,SoftDeletes;protected $fillable=['user_id','technician_code','phone','vehicle_plate','working_status','current_latitude','current_longitude','rating','note'];protected $casts=['working_status'=>TechnicianWorkingStatus::class,'current_latitude'=>'decimal:7','current_longitude'=>'decimal:7','rating'=>'decimal:2'];protected $appends=['account_name','account_email'];public function user(){return $this->belongsTo(User::class);}public function assignments(){return $this->hasMany(TechnicianAssignment::class);}public function serviceOrders(){return $this->belongsToMany(ServiceOrder::class,'technician_assignments')->withPivot(['status','assigned_at']);}public function filterReplacementHistories(){return $this->hasMany(FilterReplacementHistory::class);}public function getAccountNameAttribute(){return $this->attributes['account_name']??optional($this->user)->name;}public function setAccountNameAttribute($value){$this->attributes['account_name']=$value;}public function getAccountEmailAttribute(){return $this->attributes['account_email']??optional($this->user)->email;}public function setAccountEmailAttribute($value){$this->attributes['account_email']=$value;}public function getAccountPasswordAttribute(){return $this->attributes['account_password']??null;}public function setAccountPasswordAttribute($value){$this->attributes['account_password']=$value;}public function getAccountPasswordConfirmationAttribute(){return $this->attributes['account_password_confirmation']??null;}public function setAccountPasswordConfirmationAttribute($value){$this->attributes['account_password_confirmation']=$value;}public function clearAccountInputs(){foreach(['account_name','account_email','account_password','account_password_confirmation'] as $key)unset($this->attributes[$key]);}}
